        exercises: [
          { type: 'code', prompt: 'Del 1: Skriv `ord_lista(text)` som returnerar orden i texten med små bokstäver och utan tecknen . , ! och ? i början eller slutet. Tomma ord ska inte komma med.', starter: 'def ord_lista(text):\n    pass\n',
            tests: [{ fn: 'ord_lista', args: ['Hej hej, världen!'], expect: ['hej', 'hej', 'världen'] }, { fn: 'ord_lista', args: ['Vad? Nej.'], expect: ['vad', 'nej'] }, { fn: 'ord_lista', args: ['  !  '], expect: [], edge: 'bara tecken' }, { fn: 'ord_lista', args: [''], expect: [], edge: 'tom text' }],
            solution: 'def ord_lista(text):\n    svar = []\n    for o in text.lower().split():\n        rent = o.strip(".,!?")\n        if rent != "":\n            svar.append(rent)\n    return svar',
            explain: 'strip(".,!?") tar bort de tecknen från båda ändarna av ordet.', hint: 'split(), sedan strip(".,!?") på varje ord och hoppa över tomma.' },
          { type: 'code', prompt: 'Del 2: Skriv `topp_ord(text, n)` som returnerar de n vanligaste orden som par [ord, antal], med flest först och vid lika antal i bokstavsordning. Använd ord_lista från del 1.', starter: 'def ord_lista(text):\n    svar = []\n    for o in text.lower().split():\n        rent = o.strip(".,!?")\n        if rent != "":\n            svar.append(rent)\n    return svar\n\ndef topp_ord(text, n):\n    pass\n',
            tests: [{ fn: 'topp_ord', args: ['a b b c c c', 2], expect: [['c', 3], ['b', 2]] }, { fn: 'topp_ord', args: ['Ja nej, JA! nej', 5], expect: [['ja', 2], ['nej', 2]], edge: 'lika antal, och n större än antal ord' }, { fn: 'topp_ord', args: ['', 3], expect: [], edge: 'tom text' }],
            require: [R('def\\s+topp_ord[\\s\\S]*ord_lista\\s*\\(', 'Använd ord_lista() i topp_ord.')],
            solution: 'def ord_lista(text):\n    svar = []\n    for o in text.lower().split():\n        rent = o.strip(".,!?")\n        if rent != "":\n            svar.append(rent)\n    return svar\n\ndef topp_ord(text, n):\n    räkna = {}\n    for o in ord_lista(text):\n        räkna[o] = räkna.get(o, 0) + 1\n    par = sorted(räkna.items(), key=lambda p: (-p[1], p[0]))\n    return [[o, a] for o, a in par[:n]]',
            explain: 'Räkna, sortera med key och klipp ut de n första med [:n].', hint: 'Räkna med en ordbok, sortera items() med key=lambda p: (-p[1], p[0]) och ta [:n].' },
          { type: 'code', prompt: 'Del 3: Skriv `sammanfattning(text)` som returnerar en ordbok med "ord" (antal ord), "unika" (antal olika ord) och "längsta" (längsta ordet, det första vid lika, eller "" för tom text).', starter: 'def ord_lista(text):\n    svar = []\n    for o in text.lower().split():\n        rent = o.strip(".,!?")\n        if rent != "":\n            svar.append(rent)\n    return svar\n\ndef sammanfattning(text):\n    pass\n',
            tests: [{ fn: 'sammanfattning', args: ['Hej hej, fina världen!'], expect: { ord: 4, unika: 3, längsta: 'världen' } }, { fn: 'sammanfattning', args: ['ab cd'], expect: { ord: 2, unika: 2, längsta: 'ab' }, edge: 'lika långa' }, { fn: 'sammanfattning', args: [''], expect: { ord: 0, unika: 0, längsta: '' }, edge: 'tom text' }],
            solution: 'def ord_lista(text):\n    svar = []\n    for o in text.lower().split():\n        rent = o.strip(".,!?")\n        if rent != "":\n            svar.append(rent)\n    return svar\n\ndef sammanfattning(text):\n    ord = ord_lista(text)\n    längsta = max(ord, key=len) if ord else ""\n    return {"ord": len(ord), "unika": len(set(ord)), "längsta": längsta}',
            explain: 'set() räknar unika ord, och max med key=len hittar det längsta.', hint: 'Hämta orden med ord_lista, använd len, set och max(..., key=len).' },
        ],
