            tests: [{ fn: 'behandla', args: [{ penna: 5, block: 1 }, [['penna', -2], ['block', -3], ['sudd', 4]]], expect: ['block'] }, { fn: 'behandla', args: [{}, [['x', -1], ['y', -1]]], expect: ['x', 'y'], edge: 'allt misslyckas' }, { fn: 'behandla', args: [{ a: 1 }, []], expect: [], edge: 'tom order' }],
